        # [doc = " # Basic API"] impl Arg { # [doc = " Create a new [`Arg`] with a unique name."] # [doc = ""] # [doc = " The name is used to check whether or not the argument was used at"] # [doc = " runtime, get values, set relationships with other args, etc.."] # [doc = ""] # [doc = " By default, an `Arg` is"] # [doc = " - Positional, see [`Arg::short`] or [`Arg::long`] turn it into an option"] # [doc = " - Accept a single value, see [`Arg::action`] to override this"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** In the case of arguments that take values (i.e. [`Arg::action(ArgAction::Set)`])"] # [doc = " and positional arguments (i.e. those without a preceding `-` or `--`) the name will also"] # [doc = " be displayed when the user prints the usage/help information of the program."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg};"] # [doc = " Arg::new(\"config\")"] # [doc = " # ;"] # [doc = " ```"] # [doc = " [`Arg::action(ArgAction::Set)`]: Arg::action()"] pub fn new (id : impl Into < Id >) -> Self { Arg :: default () . id (id) } # [doc = " Set the identifier used for referencing this argument in the clap API."] # [doc = ""] # [doc = " See [`Arg::new`] for more details."] # [must_use] pub fn id (mut self , id : impl Into < Id >) -> Self { self . id = id . into () ; self } # [doc = " Sets the short version of the argument without the preceding `-`."] # [doc = ""] # [doc = " By default `V` and `h` are used by the auto-generated `version` and `help` arguments,"] # [doc = " respectively. You will need to disable the auto-generated flags"] # [doc = " ([`disable_help_flag`][crate::Command::disable_help_flag],"] # [doc = " [`disable_version_flag`][crate::Command::disable_version_flag]) and define your own."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " When calling `short`, use a single valid UTF-8 character which will allow using the"] # [doc = " argument via a single hyphen (`-`) such as `-c`:"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg,  ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"config\")"] # [doc = "         .short('c')"] # [doc = "         .action(ArgAction::Set))"] # [doc = "     .get_matches_from(vec!["] # [doc = "         \"prog\", \"-c\", \"file.toml\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert_eq!(m.get_one::<String>(\"config\").map(String::as_str), Some(\"file.toml\"));"] # [doc = " ```"] # [doc = ""] # [doc = " To use `-h` for your own flag and still have help:"] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg,  ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "     .disable_help_flag(true)"] # [doc = "     .arg(Arg::new(\"host\")"] # [doc = "         .short('h')"] # [doc = "         .long(\"host\"))"] # [doc = "     .arg(Arg::new(\"help\")"] # [doc = "         .long(\"help\")"] # [doc = "         .global(true)"] # [doc = "         .action(ArgAction::Help))"] # [doc = "     .get_matches_from(vec!["] # [doc = "         \"prog\", \"-h\", \"wikipedia.org\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert_eq!(m.get_one::<String>(\"host\").map(String::as_str), Some(\"wikipedia.org\"));"] # [doc = " ```"] # [inline] # [must_use] pub fn short (mut self , s : impl IntoResettable < char >) -> Self { if let Some (s) = s . into_resettable () . into_option () { debug_assert ! (s != '-' , "short option name cannot be `-`") ; self . short = Some (s) ; } else { self . short = None ; } self } # [doc = " Sets the long version of the argument without the preceding `--`."] # [doc = ""] # [doc = " By default `version` and `help` are used by the auto-generated `version` and `help`"] # [doc = " arguments, respectively. You may use the word `version` or `help` for the long form of your"] # [doc = " own arguments, in which case `clap` simply will not assign those to the auto-generated"] # [doc = " `version` or `help` arguments."] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** Any leading `-` characters will be stripped"] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " To set `long` use a word containing valid UTF-8. If you supply a double leading"] # [doc = " `--` such as `--config` they will be stripped. Hyphens in the middle of the word, however,"] # [doc = " will *not* be stripped (i.e. `config-file` is allowed)."] # [doc = ""] # [doc = " Setting `long` allows using the argument via a double hyphen (`--`) such as `--config`"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"cfg\")"] # [doc = "         .long(\"config\")"] # [doc = "         .action(ArgAction::Set))"] # [doc = "     .get_matches_from(vec!["] # [doc = "         \"prog\", \"--config\", \"file.toml\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert_eq!(m.get_one::<String>(\"cfg\").map(String::as_str), Some(\"file.toml\"));"] # [doc = " ```"] # [inline] # [must_use] pub fn long (mut self , l : impl IntoResettable < Str >) -> Self { self . long = l . into_resettable () . into_option () ; self } # [doc = " Add an alias, which functions as a hidden long flag."] # [doc = ""] # [doc = " This is more efficient, and easier than creating multiple hidden arguments as one only"] # [doc = " needs to check for the existence of this command, and not all variants."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "             .arg(Arg::new(\"test\")"] # [doc = "             .long(\"test\")"] # [doc = "             .alias(\"alias\")"] # [doc = "             .action(ArgAction::Set))"] # [doc = "        .get_matches_from(vec!["] # [doc = "             \"prog\", \"--alias\", \"cool\""] # [doc = "         ]);"] # [doc = " assert_eq!(m.get_one::<String>(\"test\").unwrap(), \"cool\");"] # [doc = " ```"] # [must_use] pub fn alias (mut self , name : impl IntoResettable < Str >) -> Self { if let Some (name) = name . into_resettable () . into_option () { self . aliases . push ((name , false)) ; } else { self . aliases . clear () ; } self } # [doc = " Add an alias, which functions as a hidden short flag."] # [doc = ""] # [doc = " This is more efficient, and easier than creating multiple hidden arguments as one only"] # [doc = " needs to check for the existence of this command, and not all variants."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "             .arg(Arg::new(\"test\")"] # [doc = "             .short('t')"] # [doc = "             .short_alias('e')"] # [doc = "             .action(ArgAction::Set))"] # [doc = "        .get_matches_from(vec!["] # [doc = "             \"prog\", \"-e\", \"cool\""] # [doc = "         ]);"] # [doc = " assert_eq!(m.get_one::<String>(\"test\").unwrap(), \"cool\");"] # [doc = " ```"] # [must_use] pub fn short_alias (mut self , name : impl IntoResettable < char >) -> Self { if let Some (name) = name . into_resettable () . into_option () { debug_assert ! (name != '-' , "short alias name cannot be `-`") ; self . short_aliases . push ((name , false)) ; } else { self . short_aliases . clear () ; } self } # [doc = " Add aliases, which function as hidden long flags."] # [doc = ""] # [doc = " This is more efficient, and easier than creating multiple hidden subcommands as one only"] # [doc = " needs to check for the existence of this command, and not all variants."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "             .arg(Arg::new(\"test\")"] # [doc = "                     .long(\"test\")"] # [doc = "                     .aliases([\"do-stuff\", \"do-tests\", \"tests\"])"] # [doc = "                     .action(ArgAction::SetTrue)"] # [doc = "                     .help(\"the file to add\")"] # [doc = "                     .required(false))"] # [doc = "             .get_matches_from(vec!["] # [doc = "                 \"prog\", \"--do-tests\""] # [doc = "             ]);"] # [doc = " assert_eq!(m.get_flag(\"test\"), true);"] # [doc = " ```"] # [must_use] pub fn aliases (mut self , names : impl IntoIterator < Item = impl Into < Str > >) -> Self { self . aliases . extend (names . into_iter () . map (| x | (x . into () , false))) ; self } # [doc = " Add aliases, which functions as a hidden short flag."] # [doc = ""] # [doc = " This is more efficient, and easier than creating multiple hidden subcommands as one only"] # [doc = " needs to check for the existence of this command, and not all variants."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "             .arg(Arg::new(\"test\")"] # [doc = "                     .short('t')"] # [doc = "                     .short_aliases(['e', 's'])"] # [doc = "                     .action(ArgAction::SetTrue)"] # [doc = "                     .help(\"the file to add\")"] # [doc = "                     .required(false))"] # [doc = "             .get_matches_from(vec!["] # [doc = "                 \"prog\", \"-s\""] # [doc = "             ]);"] # [doc = " assert_eq!(m.get_flag(\"test\"), true);"] # [doc = " ```"] # [must_use] pub fn short_aliases (mut self , names : impl IntoIterator < Item = char >) -> Self { for s in names { debug_assert ! (s != '-' , "short alias name cannot be `-`") ; self . short_aliases . push ((s , false)) ; } self } # [doc = " Add an alias, which functions as a visible long flag."] # [doc = ""] # [doc = " Like [`Arg::alias`], except that they are visible inside the help message."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "             .arg(Arg::new(\"test\")"] # [doc = "                 .visible_alias(\"something-awesome\")"] # [doc = "                 .long(\"test\")"] # [doc = "                 .action(ArgAction::Set))"] # [doc = "        .get_matches_from(vec!["] # [doc = "             \"prog\", \"--something-awesome\", \"coffee\""] # [doc = "         ]);"] # [doc = " assert_eq!(m.get_one::<String>(\"test\").unwrap(), \"coffee\");"] # [doc = " ```"] # [doc = " [`Command::alias`]: Arg::alias()"] # [must_use] pub fn visible_alias (mut self , name : impl IntoResettable < Str >) -> Self { if let Some (name) = name . into_resettable () . into_option () { self . aliases . push ((name , true)) ; } else { self . aliases . clear () ; } self } # [doc = " Add an alias, which functions as a visible short flag."] # [doc = ""] # [doc = " Like [`Arg::short_alias`], except that they are visible inside the help message."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "             .arg(Arg::new(\"test\")"] # [doc = "                 .long(\"test\")"] # [doc = "                 .visible_short_alias('t')"] # [doc = "                 .action(ArgAction::Set))"] # [doc = "        .get_matches_from(vec!["] # [doc = "             \"prog\", \"-t\", \"coffee\""] # [doc = "         ]);"] # [doc = " assert_eq!(m.get_one::<String>(\"test\").unwrap(), \"coffee\");"] # [doc = " ```"] # [must_use] pub fn visible_short_alias (mut self , name : impl IntoResettable < char >) -> Self { if let Some (name) = name . into_resettable () . into_option () { debug_assert ! (name != '-' , "short alias name cannot be `-`") ; self . short_aliases . push ((name , true)) ; } else { self . short_aliases . clear () ; } self } # [doc = " Add aliases, which function as visible long flags."] # [doc = ""] # [doc = " Like [`Arg::aliases`], except that they are visible inside the help message."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "             .arg(Arg::new(\"test\")"] # [doc = "                 .long(\"test\")"] # [doc = "                 .action(ArgAction::SetTrue)"] # [doc = "                 .visible_aliases([\"something\", \"awesome\", \"cool\"]))"] # [doc = "        .get_matches_from(vec!["] # [doc = "             \"prog\", \"--awesome\""] # [doc = "         ]);"] # [doc = " assert_eq!(m.get_flag(\"test\"), true);"] # [doc = " ```"] # [doc = " [`Command::aliases`]: Arg::aliases()"] # [must_use] pub fn visible_aliases (mut self , names : impl IntoIterator < Item = impl Into < Str > >) -> Self { self . aliases . extend (names . into_iter () . map (| n | (n . into () , true))) ; self } # [doc = " Add aliases, which function as visible short flags."] # [doc = ""] # [doc = " Like [`Arg::short_aliases`], except that they are visible inside the help message."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "             .arg(Arg::new(\"test\")"] # [doc = "                 .long(\"test\")"] # [doc = "                 .action(ArgAction::SetTrue)"] # [doc = "                 .visible_short_aliases(['t', 'e']))"] # [doc = "        .get_matches_from(vec!["] # [doc = "             \"prog\", \"-t\""] # [doc = "         ]);"] # [doc = " assert_eq!(m.get_flag(\"test\"), true);"] # [doc = " ```"] # [must_use] pub fn visible_short_aliases (mut self , names : impl IntoIterator < Item = char >) -> Self { for n in names { debug_assert ! (n != '-' , "short alias name cannot be `-`") ; self . short_aliases . push ((n , true)) ; } self } # [doc = " Specifies the index of a positional argument **starting at** 1."] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** The index refers to position according to **other positional argument**. It does"] # [doc = " not define position in the argument list as a whole."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** You can optionally leave off the `index` method, and the index will be"] # [doc = " assigned in order of evaluation. Utilizing the `index` method allows for setting"] # [doc = " indexes out of order"] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** This is only meant to be used for positional arguments and shouldn't to be used"] # [doc = " with [`Arg::short`] or [`Arg::long`]."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** When utilized with [`Arg::num_args(1..)`][Arg::num_args], only the **last** positional argument"] # [doc = " may be defined as having a variable number of arguments (i.e. with the highest index)"] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " [`Command`] will [`panic!`] if indexes are skipped (such as defining `index(1)` and `index(3)`"] # [doc = " but not `index(2)`, or a positional argument is defined as multiple and is not the highest"] # [doc = " index (debug builds)"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg};"] # [doc = " Arg::new(\"config\")"] # [doc = "     .index(1)"] # [doc = " # ;"] # [doc = " ```"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"mode\")"] # [doc = "         .index(1))"] # [doc = "     .arg(Arg::new(\"debug\")"] # [doc = "         .long(\"debug\")"] # [doc = "         .action(ArgAction::SetTrue))"] # [doc = "     .get_matches_from(vec!["] # [doc = "         \"prog\", \"--debug\", \"fast\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert!(m.contains_id(\"mode\"));"] # [doc = " assert_eq!(m.get_one::<String>(\"mode\").unwrap(), \"fast\"); // notice index(1) means \"first positional\""] # [doc = "                                                           // *not* first argument"] # [doc = " ```"] # [doc = " [`Arg::short`]: Arg::short()"] # [doc = " [`Arg::long`]: Arg::long()"] # [doc = " [`Arg::num_args(true)`]: Arg::num_args()"] # [doc = " [`Command`]: crate::Command"] # [inline] # [must_use] pub fn index (mut self , idx : impl IntoResettable < usize >) -> Self { self . index = idx . into_resettable () . into_option () ; self } # [doc = " This is a \"var arg\" and everything that follows should be captured by it, as if the user had"] # [doc = " used a `--`."] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** To start the trailing \"var arg\" on unknown flags (and not just a positional"] # [doc = " value), set [`allow_hyphen_values`][Arg::allow_hyphen_values].  Either way, users still"] # [doc = " have the option to explicitly escape ambiguous arguments with `--`."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** [`Arg::value_delimiter`] still applies if set."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** Setting this requires [`Arg::num_args(..)`]."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, arg};"] # [doc = " let m = Command::new(\"myprog\")"] # [doc = "     .arg(arg!(<cmd> ... \"commands to run\").trailing_var_arg(true))"] # [doc = "     .get_matches_from(vec![\"myprog\", \"arg1\", \"-r\", \"val1\"]);"] # [doc = ""] # [doc = " let trail: Vec<_> = m.get_many::<String>(\"cmd\").unwrap().collect();"] # [doc = " assert_eq!(trail, [\"arg1\", \"-r\", \"val1\"]);"] # [doc = " ```"] # [doc = " [`Arg::num_args(..)`]: crate::Arg::num_args()"] pub fn trailing_var_arg (self , yes : bool) -> Self { if yes { self . setting (ArgSettings :: TrailingVarArg) } else { self . unset_setting (ArgSettings :: TrailingVarArg) } } # [doc = " This arg is the last, or final, positional argument (i.e. has the highest"] # [doc = " index) and is *only* able to be accessed via the `--` syntax (i.e. `$ prog args --"] # [doc = " last_arg`)."] # [doc = ""] # [doc = " Even, if no other arguments are left to parse, if the user omits the `--` syntax"] # [doc = " they will receive an [`UnknownArgument`] error. Setting an argument to `.last(true)` also"] # [doc = " allows one to access this arg early using the `--` syntax. Accessing an arg early, even with"] # [doc = " the `--` syntax is otherwise not possible."] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** This will change the usage string to look like `$ prog [OPTIONS] [-- <ARG>]` if"] # [doc = " `ARG` is marked as `.last(true)`."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** This setting will imply [`crate::Command::dont_collapse_args_in_usage`] because failing"] # [doc = " to set this can make the usage string very confusing."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE**: This setting only applies to positional arguments, and has no effect on OPTIONS"] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** Setting this requires [taking values][Arg::num_args]"] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **WARNING:** Using this setting *and* having child subcommands is not"] # [doc = " recommended with the exception of *also* using"] # [doc = " [`crate::Command::args_conflicts_with_subcommands`]"] # [doc = " (or [`crate::Command::subcommand_negates_reqs`] if the argument marked `Last` is also"] # [doc = " marked [`Arg::required`])"] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Arg, ArgAction};"] # [doc = " Arg::new(\"args\")"] # [doc = "     .action(ArgAction::Set)"] # [doc = "     .last(true)"] # [doc = " # ;"] # [doc = " ```"] # [doc = ""] # [doc = " Setting `last` ensures the arg has the highest [index] of all positional args"] # [doc = " and requires that the `--` syntax be used to access it early."] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let res = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"first\"))"] # [doc = "     .arg(Arg::new(\"second\"))"] # [doc = "     .arg(Arg::new(\"third\")"] # [doc = "         .action(ArgAction::Set)"] # [doc = "         .last(true))"] # [doc = "     .try_get_matches_from(vec!["] # [doc = "         \"prog\", \"one\", \"--\", \"three\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert!(res.is_ok());"] # [doc = " let m = res.unwrap();"] # [doc = " assert_eq!(m.get_one::<String>(\"third\").unwrap(), \"three\");"] # [doc = " assert_eq!(m.get_one::<String>(\"second\"), None);"] # [doc = " ```"] # [doc = ""] # [doc = " Even if the positional argument marked `Last` is the only argument left to parse,"] # [doc = " failing to use the `--` syntax results in an error."] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, error::ErrorKind, ArgAction};"] # [doc = " let res = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"first\"))"] # [doc = "     .arg(Arg::new(\"second\"))"] # [doc = "     .arg(Arg::new(\"third\")"] # [doc = "         .action(ArgAction::Set)"] # [doc = "         .last(true))"] # [doc = "     .try_get_matches_from(vec!["] # [doc = "         \"prog\", \"one\", \"two\", \"three\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert!(res.is_err());"] # [doc = " assert_eq!(res.unwrap_err().kind(), ErrorKind::UnknownArgument);"] # [doc = " ```"] # [doc = " [index]: Arg::index()"] # [doc = " [`UnknownArgument`]: crate::error::ErrorKind::UnknownArgument"] # [inline] # [must_use] pub fn last (self , yes : bool) -> Self { if yes { self . setting (ArgSettings :: Last) } else { self . unset_setting (ArgSettings :: Last) } } # [doc = " Specifies that the argument must be present."] # [doc = ""] # [doc = " Required by default means it is required, when no other conflicting rules or overrides have"] # [doc = " been evaluated. Conflicting rules take precedence over being required."] # [doc = ""] # [doc = " **Pro tip:** Flags (i.e. not positional, or arguments that take values) shouldn't be"] # [doc = " required by default. This is because if a flag were to be required, it should simply be"] # [doc = " implied. No additional information is required from user. Flags by their very nature are"] # [doc = " simply boolean on/off switches. The only time a user *should* be required to use a flag"] # [doc = " is if the operation is destructive in nature, and the user is essentially proving to you,"] # [doc = " \"Yes, I know what I'm doing.\""] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::Arg;"] # [doc = " Arg::new(\"config\")"] # [doc = "     .required(true)"] # [doc = " # ;"] # [doc = " ```"] # [doc = ""] # [doc = " Setting required requires that the argument be used at runtime."] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let res = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"cfg\")"] # [doc = "         .required(true)"] # [doc = "         .action(ArgAction::Set)"] # [doc = "         .long(\"config\"))"] # [doc = "     .try_get_matches_from(vec!["] # [doc = "         \"prog\", \"--config\", \"file.conf\","] # [doc = "     ]);"] # [doc = ""] # [doc = " assert!(res.is_ok());"] # [doc = " ```"] # [doc = ""] # [doc = " Setting required and then *not* supplying that argument at runtime is an error."] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, error::ErrorKind, ArgAction};"] # [doc = " let res = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"cfg\")"] # [doc = "         .required(true)"] # [doc = "         .action(ArgAction::Set)"] # [doc = "         .long(\"config\"))"] # [doc = "     .try_get_matches_from(vec!["] # [doc = "         \"prog\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert!(res.is_err());"] # [doc = " assert_eq!(res.unwrap_err().kind(), ErrorKind::MissingRequiredArgument);"] # [doc = " ```"] # [inline] # [must_use] pub fn required (self , yes : bool) -> Self { if yes { self . setting (ArgSettings :: Required) } else { self . unset_setting (ArgSettings :: Required) } } # [doc = " Sets an argument that is required when this one is present"] # [doc = ""] # [doc = " i.e. when using this argument, the following argument *must* be present."] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** [Conflicting] rules and [override] rules take precedence over being required"] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::Arg;"] # [doc = " Arg::new(\"config\")"] # [doc = "     .requires(\"input\")"] # [doc = " # ;"] # [doc = " ```"] # [doc = ""] # [doc = " Setting [`Arg::requires(name)`] requires that the argument be used at runtime if the"] # [doc = " defining argument is used. If the defining argument isn't used, the other argument isn't"] # [doc = " required"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let res = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"cfg\")"] # [doc = "         .action(ArgAction::Set)"] # [doc = "         .requires(\"input\")"] # [doc = "         .long(\"config\"))"] # [doc = "     .arg(Arg::new(\"input\"))"] # [doc = "     .try_get_matches_from(vec!["] # [doc = "         \"prog\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert!(res.is_ok()); // We didn't use cfg, so input wasn't required"] # [doc = " ```"] # [doc = ""] # [doc = " Setting [`Arg::requires(name)`] and *not* supplying that argument is an error."] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, error::ErrorKind, ArgAction};"] # [doc = " let res = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"cfg\")"] # [doc = "         .action(ArgAction::Set)"] # [doc = "         .requires(\"input\")"] # [doc = "         .long(\"config\"))"] # [doc = "     .arg(Arg::new(\"input\"))"] # [doc = "     .try_get_matches_from(vec!["] # [doc = "         \"prog\", \"--config\", \"file.conf\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert!(res.is_err());"] # [doc = " assert_eq!(res.unwrap_err().kind(), ErrorKind::MissingRequiredArgument);"] # [doc = " ```"] # [doc = " [`Arg::requires(name)`]: Arg::requires()"] # [doc = " [Conflicting]: Arg::conflicts_with()"] # [doc = " [override]: Arg::overrides_with()"] # [must_use] pub fn requires (mut self , arg_id : impl IntoResettable < Id >) -> Self { if let Some (arg_id) = arg_id . into_resettable () . into_option () { self . requires . push ((ArgPredicate :: IsPresent , arg_id)) ; } else { self . requires . clear () ; } self } # [doc = " This argument must be passed alone; it conflicts with all other arguments."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::Arg;"] # [doc = " Arg::new(\"config\")"] # [doc = "     .exclusive(true)"] # [doc = " # ;"] # [doc = " ```"] # [doc = ""] # [doc = " Setting an exclusive argument and having any other arguments present at runtime"] # [doc = " is an error."] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, error::ErrorKind, ArgAction};"] # [doc = " let res = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"exclusive\")"] # [doc = "         .action(ArgAction::Set)"] # [doc = "         .exclusive(true)"] # [doc = "         .long(\"exclusive\"))"] # [doc = "     .arg(Arg::new(\"debug\")"] # [doc = "         .long(\"debug\"))"] # [doc = "     .arg(Arg::new(\"input\"))"] # [doc = "     .try_get_matches_from(vec!["] # [doc = "         \"prog\", \"--exclusive\", \"file.conf\", \"file.txt\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert!(res.is_err());"] # [doc = " assert_eq!(res.unwrap_err().kind(), ErrorKind::ArgumentConflict);"] # [doc = " ```"] # [inline] # [must_use] pub fn exclusive (self , yes : bool) -> Self { if yes { self . setting (ArgSettings :: Exclusive) } else { self . unset_setting (ArgSettings :: Exclusive) } } # [doc = " Specifies that an argument can be matched to all child [`Subcommand`]s."] # [doc = ""] # [doc = " <div class=\"warning\">"] # [doc = ""] # [doc = " **NOTE:** Global arguments *only* propagate down, **not** up (to parent commands), however"] # [doc = " their values once a user uses them will be propagated back up to parents. In effect, this"] # [doc = " means one should *define* all global arguments at the top level, however it doesn't matter"] # [doc = " where the user *uses* the global argument."] # [doc = ""] # [doc = " </div>"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Assume an application with two subcommands, and you'd like to define a"] # [doc = " `--verbose` flag that can be called on any of the subcommands and parent, but you don't"] # [doc = " want to clutter the source with three duplicate [`Arg`] definitions."] # [doc = ""] # [doc = " ```rust"] # [doc = " # use clap_builder as clap;"] # [doc = " # use clap::{Command, Arg, ArgAction};"] # [doc = " let m = Command::new(\"prog\")"] # [doc = "     .arg(Arg::new(\"verb\")"] # [doc = "         .long(\"verbose\")"] # [doc = "         .short('v')"] # [doc = "         .action(ArgAction::SetTrue)"] # [doc = "         .global(true))"] # [doc = "     .subcommand(Command::new(\"test\"))"] # [doc = "     .subcommand(Command::new(\"do-stuff\"))"] # [doc = "     .get_matches_from(vec!["] # [doc = "         \"prog\", \"do-stuff\", \"--verbose\""] # [doc = "     ]);"] # [doc = ""] # [doc = " assert_eq!(m.subcommand_name(), Some(\"do-stuff\"));"] # [doc = " let sub_m = m.subcommand_matches(\"do-stuff\").unwrap();"] # [doc = " assert_eq!(sub_m.get_flag(\"verb\"), true);"] # [doc = " ```"] # [doc = ""] # [doc = " [`Subcommand`]: crate::Subcommand"] # [inline] # [must_use] pub fn global (self , yes : bool) -> Self { if yes { self . setting (ArgSettings :: Global) } else { self . unset_setting (ArgSettings :: Global) } } # [inline] pub (crate) fn is_set (& self , s : ArgSettings) -> bool { self . settings . is_set (s) } # [inline] # [must_use] pub (crate) fn setting (mut self , setting : ArgSettings) -> Self { self . settings . set (setting) ; self } # [inline] # [must_use] pub (crate) fn unset_setting (mut self , setting : ArgSettings) -> Self { self . settings . unset (setting) ; self } # [doc = " Extend [`Arg`] with [`ArgExt`] data"] # [cfg (feature = "unstable-ext")] # [allow (clippy :: should_implement_trait)] pub fn add < T : ArgExt + Extension > (mut self , tagged : T) -> Self { self . ext . set (tagged) ; self } }
